class Employee:
    def __init__(self, employee_id, manager_id):
        self.employee_id = employee_id
        self.manager_id = manager_id
        self.subordinates = []

def build_tree(employees):
    employee_map = {}
    root = None
    for emp in employees:
        if emp.employee_id not in employee_map:
            employee_map[emp.employee_id] = Employee(emp.employee_id, emp.manager_id)
        if emp.manager_id is None:
            root = employee_map[emp.employee_id]
        else:
            if emp.manager_id not in employee_map:
                employee_map[emp.manager_id] = Employee(emp.manager_id, None)
            employee_map[emp.manager_id].subordinates.append(employee_map[emp.employee_id])
    return root

